import React from 'react';
import { Transaction, TransactionStatus } from '../types';
import { MoreHorizontal } from 'lucide-react';

interface RecentTransactionsProps {
  transactions: Transaction[];
}

const RecentTransactions: React.FC<RecentTransactionsProps> = ({ transactions }) => {
  const getStatusStyle = (status: TransactionStatus) => {
    switch (status) {
      case TransactionStatus.COMPLETED:
        return 'bg-green-50 text-green-700 border-green-200';
      case TransactionStatus.PENDING:
        return 'bg-yellow-50 text-yellow-700 border-yellow-200';
      case TransactionStatus.FAILED:
        return 'bg-red-50 text-red-700 border-red-200';
      default:
        return 'bg-gray-50 text-gray-700 border-gray-200';
    }
  };

  return (
    <div className="overflow-x-auto">
      <table className="w-full">
        <thead>
          <tr className="border-b border-gray-100">
            <th className="text-left text-xs font-semibold text-gray-500 uppercase tracking-wider py-4 px-2">Transaction ID</th>
            <th className="text-left text-xs font-semibold text-gray-500 uppercase tracking-wider py-4 px-2">Customer</th>
            <th className="text-left text-xs font-semibold text-gray-500 uppercase tracking-wider py-4 px-2">Date</th>
            <th className="text-left text-xs font-semibold text-gray-500 uppercase tracking-wider py-4 px-2">Amount</th>
            <th className="text-left text-xs font-semibold text-gray-500 uppercase tracking-wider py-4 px-2">Status</th>
            <th className="text-right text-xs font-semibold text-gray-500 uppercase tracking-wider py-4 px-2">Action</th>
          </tr>
        </thead>
        <tbody>
          {transactions.map((transaction) => (
            <tr key={transaction.id} className="group hover:bg-gray-50 transition-colors">
              <td className="py-4 px-2 text-sm text-gray-900 font-medium">{transaction.id}</td>
              <td className="py-4 px-2">
                <div className="flex items-center space-x-3">
                  <img 
                    src={transaction.avatar} 
                    alt={transaction.user} 
                    className="w-8 h-8 rounded-full bg-gray-200"
                  />
                  <div>
                    <p className="text-sm font-medium text-gray-900">{transaction.user}</p>
                    <p className="text-xs text-gray-500">{transaction.method}</p>
                  </div>
                </div>
              </td>
              <td className="py-4 px-2 text-sm text-gray-500">{transaction.date}</td>
              <td className="py-4 px-2 text-sm font-medium text-gray-900">{transaction.amount}</td>
              <td className="py-4 px-2">
                <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium border ${getStatusStyle(transaction.status)}`}>
                  {transaction.status}
                </span>
              </td>
              <td className="py-4 px-2 text-right">
                <button className="text-gray-400 hover:text-gray-600 transition-colors p-1 rounded-md hover:bg-gray-100">
                  <MoreHorizontal className="w-5 h-5" />
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default RecentTransactions;

import React from 'react';
