interface SidebarProps {
  currentView: ViewState;
  onChangeView: (view: ViewState) => void;
  isOpen: boolean;
}

const Sidebar: React.FC<SidebarProps> = ({ currentView, onChangeView, isOpen }) => {
  const menuItems = [
    { id: ViewState.DASHBOARD, label: 'Dashboard', icon: LayoutDashboard },
    { id: ViewState.ANALYTICS, label: 'Analytics', icon: PieChart },
    { id: ViewState.CUSTOMERS, label: 'Customers', icon: Users },
    { id: ViewState.SETTINGS, label: 'Settings', icon: Settings },
  ];

  return (
    <aside 
      className={`
        fixed top-0 left-0 z-40 h-screen transition-transform bg-white border-r border-gray-100
        ${isOpen ? 'translate-x-0' : '-translate-x-full'} 
        md:translate-x-0 w-64
      `}
    >
      <div className="flex flex-col h-full px-6 py-6">
        {/* Logo */}
        <div className="flex items-center space-x-3 mb-10 px-2">
          <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center">
            <PieChart className="w-5 h-5 text-white" />
          </div>
          <span className="text-xl font-bold text-gray-900 tracking-tight">Lumina</span>
        </div>

        {/* Navigation */}
        <nav className="flex-1 space-y-1">
          {menuItems.map((item) => {
            const Icon = item.icon;
            const isActive = currentView === item.id;

            return (
              <button
                key={item.id}
                onClick={() => onChangeView(item.id)}
                className={`
                  w-full flex items-center space-x-3 px-3 py-3 rounded-xl text-sm font-medium transition-all duration-200
                  ${isActive 
                    ? 'bg-indigo-50 text-indigo-600' 
                    : 'text-gray-600 hover:bg-gray-50 hover:text-gray-900'}
                `}
              >
                <Icon className={`w-5 h-5 ${isActive ? 'text-indigo-600' : 'text-gray-400'}`} />
                <span>{item.label}</span>
              </button>
            );
          })}
        </nav>

        {/* Secondary Navigation */}
        <div className="pt-6 border-t border-gray-100 space-y-1">
          <button className="w-full flex items-center space-x-3 px-3 py-3 rounded-xl text-sm font-medium text-gray-600 hover:bg-gray-50 hover:text-gray-900 transition-colors">
            <FileText className="w-5 h-5 text-gray-400" />
