              <h2 className="text-2xl font-semibold text-gray-900 mb-2">Customer Management</h2>
              <p>Customer CRM module coming soon.</p>
            </div>
          </div>
        );
      case ViewState.SETTINGS:
        return (
           <div className="flex items-center justify-center h-[calc(100vh-100px)] text-gray-500">
            <div className="text-center">
              <h2 className="text-2xl font-semibold text-gray-900 mb-2">Settings</h2>
              <p>System configuration coming soon.</p>
            </div>
          </div>
        );
      default:
        return <DashboardPage />;
    }
  };

  return (
    <div className="min-h-screen bg-[#f3f4f6]">
      {/* Mobile Header */}
      <div className="md:hidden bg-white border-b border-gray-100 px-4 py-3 flex items-center justify-between sticky top-0 z-30">
        <div className="flex items-center space-x-2">
           <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center">
