interface StatCardProps {
  data: StatData;
}

const StatCard: React.FC<StatCardProps> = ({ data }) => {
  const { title, value, change, trend, icon: Icon, color, highlight } = data;

  // Extract numerical value and formatting details for NumberTicker
  const numericValue = parseFloat(value.replace(/[^0-9.]/g, ''));
  const prefix = value.match(/^[^0-9]*/) ? value.match(/^[^0-9]*/)![0] : '';
  const suffix = value.match(/[^0-9]*$/) ? value.match(/[^0-9]*$/)![0] : '';
  const decimalPlaces = value.includes('.') ? value.split('.')[1].length : 0;


  // Map incoming Tailwind text colors to hex values for background opacity
  const getColorHex = (twClass: string) => {
      if (twClass.includes('indigo')) return '#6366f1';
      if (twClass.includes('emerald')) return '#10b981';
      if (twClass.includes('amber')) return '#f59e0b';
      if (twClass.includes('pink')) return '#ec4899';
      return '#6C5CE7'; // Default accent
  };

  const getTrendIcon = () => {
    switch (trend) {
      case 'up':
        return <ArrowUpRight className="w-3.5 h-3.5 text-[#4ADE80]" />;
      case 'down':
        return <ArrowDownRight className="w-3.5 h-3.5 text-red-400" />;
      default:
        return <Minus className="w-3.5 h-3.5 text-gray-400" />;
    }
  };

  const getTrendStyle = () => {
    switch (trend) {
      case 'up':
        return 'text-[#4ADE80] bg-[#4ADE80]/10 border border-[#4ADE80]/20';
      case 'down':
        return 'text-red-400 bg-red-400/10 border border-red-400/20';
      default:
        return 'text-gray-400 bg-gray-400/10 border border-gray-400/20';
    }
  };

  return (
    <div className={cn(
      "relative bg-[#151518] p-6 rounded-2xl border border-white/5 transition-all duration-300 group overflow-hidden",
      highlight ? "shadow-[0_0_40px_-10px_rgba(108,92,231,0.3)]" : "hover:border-white/10 hover:shadow-[0_8px_30px_rgb(0,0,0,0.12)]"
    )}>
      {highlight && <BorderBeam size={250} duration={12} delay={9} colorFrom="#6C5CE7" colorTo="#F43F5E" />}

      <div className="flex justify-between items-start mb-4 relative z-10">
        <div 
          className="p-3 rounded-xl transition-colors duration-300" 
          style={{ backgroundColor: `${getColorHex(color)}15`, color: getColorHex(color) }}
        >
          <Icon className="w-6 h-6" />
        </div>
        <div className={`flex items-center space-x-1 text-xs font-semibold px-2.5 py-1 rounded-full ${getTrendStyle()}`}>
          {getTrendIcon()}
          <span>{change}</span>
        </div>
      </div>
      <div className="relative z-10">
        <h3 className="text-gray-400 text-sm font-medium mb-1 group-hover:text-gray-300 transition-colors">{title}</h3>
        <div className="text-2xl font-bold text-white tracking-tight flex items-center">
            {prefix}
            <NumberTicker 
                value={numericValue} 
                decimalPlaces={decimalPlaces}
                className="text-white"
            />
            {suffix}
        </div>
      </div>
    </div>
  );
};

export default StatCard;

